import { Client, Environment, OrdersController, SubscriptionsController } from '@paypal/paypal-server-sdk';
import { PAYPAL_BASE_URL, platformCredentials } from './config.ts';

// PayPal Server SDK (generated by APIMatic) for Orders and Subscriptions.

let controllers: { orders: OrdersController; subscriptions: SubscriptionsController } | undefined;

export function sdk() {
  if (!controllers) {
    const creds = platformCredentials();
    const client = new Client({
      clientCredentialsAuthCredentials: { oAuthClientId: creds.clientId, oAuthClientSecret: creds.clientSecret },
      environment: PAYPAL_BASE_URL.includes('sandbox') ? Environment.Sandbox : Environment.Production,
      timeout: 30_000,
    });
    controllers = { orders: new OrdersController(client), subscriptions: new SubscriptionsController(client) };
  }
  return controllers;
}
